@extends('layouts.app') @section('title','Stock Adjustment') @section('content')@php $catalog=$products->map(fn($p)=>['id'=>$p->id,'units'=>$p->productUnits->map(fn($u)=>['id'=>$u->unit_id,'label'=>$u->unit->name.' ('.$u->unit->symbol.')'])->values()])->values(); @endphp<div class="mx-auto max-w-3xl"><a class="text-sm text-slate-500" href="{{ route('inventory.index') }}">← Inventory</a><h1 class="mt-2 font-serif text-3xl text-ink">Stock adjustment</h1><p class="mb-6 text-sm text-slate-500">Use a reasoned ledger entry; quantities are never edited directly.</p><form class="card p-6" method="post" action="{{ route('inventory.adjust.store') }}" x-data='adjust(@json($catalog))'>@csrf<div class="grid gap-5 md:grid-cols-2"><div class="md:col-span-2"><label>Product</label><select class="w-full" name="product_id" x-model.number="product" required x-init="initTomSelect($el)"><option value="">Select</option>@foreach($products as $p)<option value="{{ $p->id }}">{{ $p->name }} · {{ $p->sku }}</option>@endforeach</select></div><div><label>Store</label><select class="w-full" name="store_id">@foreach($stores as $s)<option value="{{ $s->id }}">{{ $s->name }}</option>@endforeach</select></div><div><label>Inventory</label><select class="w-full" name="inventory_type"><option value="main">Main inventory</option><option value="remnant">Remnant inventory</option></select></div><div><label>Direction</label><select class="w-full" name="direction"><option value="increase">Increase</option><option value="decrease">Decrease</option></select></div><div><label>Unit</label><select class="w-full" name="unit_id" required><template x-for="u in units"><option :value="u.id" x-text="u.label"></option></template></select></div><div><label>Quantity</label><input class="w-full" type="number" min="0.001" step="0.001" name="quantity" required></div><div><label>Reason</label><select class="w-full" name="reason"><option>Opening Stock</option><option>Damage</option><option>Missing</option><option>Measurement D